+++ b/test/capitalize.test.js
@@ -0,0 +1,17 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+
+import { capitalize } from '../src/app.js';
+
+test('capitalize returns an empty string for empty input', () => {
+  assert.equal(capitalize(''), '');
+});
+
+test('capitalize preserves the characters after the first', () => {
+  assert.equal(capitalize('hELLO'), 'HELLO');
+});
+
+test('capitalize uppercases the first character of ordinary input', () => {
+  assert.equal(capitalize('hello'), 'Hello');
+});

diff --git a/src/app.js b/src/app.js
--- a/src/app.js
+++ b/src/app.js
@@ -1,5 +1,6 @@
 export function formatDuration(total) {
-  const minutes = Math.floor(total / 60);
-  const seconds = String(total % 60).padStart(2, '0');
+  const totalSeconds = Math.floor(total);
+  const minutes = Math.floor(totalSeconds / 60);
+  const seconds = String(totalSeconds % 60).padStart(2, '0');
   return `${minutes}:${seconds}`;
 }

diff --git a/test/formatDuration.test.js b/test/formatDuration.test.js
--- a/test/formatDuration.test.js
+++ b/test/formatDuration.test.js
@@ -10,8 +10,17 @@ test('formatDuration pads zero seconds and minutes-less durations', () => {
   assert.equal(formatDuration(0), '0:00');
 });

 test('formatDuration keeps minutes and two-digit seconds', () => {
   assert.equal(formatDuration(125), '2:05');
   assert.equal(formatDuration(3600), '60:00');
 });
+
+test('formatDuration always uses two-digit seconds', () => {
+  assert.equal(formatDuration(65), '1:05');
+  assert.equal(formatDuration(65.9), '1:05');
+
+  for (let total = 0; total < 3600; total += 1) {
+    assert.match(formatDuration(total), /^\d+:\d{2}$/);
+  }
+});
